INSERT INTO public.processes (id, slug, title, urdu_title, summary, category, city, fee_normal, fee_urgent, fee_executive, fee_notes, time_required, office_name, office_address, office_timings, best_day_to_go, official_source_url, last_updated, is_verified, is_nationwide, popularity_rank) VALUES ('a1000000-0000-4000-8000-000000000001', 'passport-renewal-rawalpindi', 'Passport Renewal in Rawalpindi', 'پاسپورٹ کی تجدید — راولپنڈی', 'Complete step-by-step guide to renewing your 36-page Pakistani Machine Readable Passport (5-year validity) at Regional Passport Office Rawalpindi using Passport Fee Asaan or NBP challan.', 'Passport', 'Rawalpindi', 4500, 7500, 12500, 'Fees shown are for a 36-page, 5-year Ordinary Machine Readable Passport (DGIP standard schedule). 10-year validity costs Rs. 6,700 (Normal), Rs. 11,200 (Urgent), and Rs. 16,200 (Fast Track).', 'Normal: 21 working days | Urgent: 5 working days | Fast Track: 2 working days', 'Regional Passport Office Rawalpindi', 'Near Rehmanabad Chowk, Main Murree Road (Opposite Sixth Road Metro Station), Rawalpindi', 'Mon–Thu: 8:30 AM – 2:00 PM | Fri: 8:30 AM – 12:30 PM (Closed Sat–Sun)', 'Tuesday or Wednesday, arrive by 8:00 AM before token rush', 'https://dgip.gov.pk/passport/ordinary-passport.php', '2026-11-15T09:00:00Z', TRUE, FALSE, 1) ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.processes (id, slug, title, urdu_title, summary, category, city, fee_normal, fee_urgent, fee_executive, fee_notes, time_required, office_name, office_address, office_timings, best_day_to_go, official_source_url, last_updated, is_verified, is_nationwide, popularity_rank) VALUES ('a1000000-0000-4000-8000-000000000002', 'cnic-renewal-rawalpindi', 'CNIC Renewal in Rawalpindi', 'شناختی کارڈ کی تجدید — راولپنڈی', 'How to renew an expired or expiring Smart National Identity Card (SNIC) at NADRA Mega Center Rehmanabad Rawalpindi without paying an agent.', 'Identity', 'Rawalpindi', 750, 1500, 2500, 'Official NADRA Smart CNIC renewal fee schedule. Optional NADRA SMS alert & home courier delivery add roughly Rs. 100–250 at the counter.', 'Normal: 31 days | Urgent: 15 days | Executive: 7 days', 'NADRA Mega Center Rawalpindi (Rehmanabad)', 'Ground Floor, Rehmanabad Plaza, Main Murree Road near Rehmanabad Metro Station, Rawalpindi', 'Mon–Sat: 8:00 AM – 8:00 PM (Mega Center operates double shift; Closed Sun)', 'Wednesday or Thursday between 2:30 PM – 4:30 PM (post-lunch dip)', 'https://www.nadra.gov.pk/identity/identity-cnic', '2026-11-15T08:30:00Z', TRUE, FALSE, 2) ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.processes (id, slug, title, urdu_title, summary, category, city, fee_normal, fee_urgent, fee_executive, fee_notes, time_required, office_name, office_address, office_timings, best_day_to_go, official_source_url, last_updated, is_verified, is_nationwide, popularity_rank) VALUES ('a1000000-0000-4000-8000-000000000003', 'driving-licence-renewal-rawalpindi', 'Driving Licence Renewal in Rawalpindi', 'ڈرائیونگ لائسنس کی تجدید — راولپنڈی', 'Step-by-step instructions to renew your expired or expiring Punjab car/motorcycle driving licence at City Traffic Police Licensing Branch Rawalpindi or Khidmat Markaz.', 'Driving', 'Rawalpindi', 1800, 2800, 3800, 'Normal Rs. 1,800 covers standard 1-year Car/Jeep renewal including card & test/medical ticket. Urgent/Executive estimates reflect 3-year and 5-year Punjab DLIMS multi-year renewal options plus e-Licence download.', 'Same-day e-Licence PDF | Physical PVC card delivered in 7–15 days', 'City Traffic Police Licensing Branch Rawalpindi', 'Traffic Police Headquarters, Race Course Ground, Main Peshawar Road, Rawalpindi', 'Mon–Sat: 8:30 AM – 4:00 PM | Khidmat Markaz Liaquat Bagh open till 8:00 PM', 'Tuesday or Thursday morning at 8:30 AM (avoid Monday backlog)', 'https://dlims.punjab.gov.pk/', '2026-11-14T11:00:00Z', TRUE, FALSE, 3) ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.processes (id, slug, title, urdu_title, summary, category, city, fee_normal, fee_urgent, fee_executive, fee_notes, time_required, office_name, office_address, office_timings, best_day_to_go, official_source_url, last_updated, is_verified, is_nationwide, popularity_rank) VALUES ('a1000000-0000-4000-8000-000000000004', 'fbr-ntn-for-freelancers', 'FBR NTN Registration for Freelancers', 'فری لانسرز کے لیے ایف بی آر این ٹی این', '100% free online guide to registering your National Tax Number (NTN) on FBR IRIS portal from home so freelancers can open business bank accounts, register with PSEB, and become a Filer.', 'Tax', 'Islamabad', 0, 0, 0, 'FBR NTN registration on IRIS is completely FREE (Rs. 0). Becoming an Active Taxpayer (ATL Filer) only requires filing your annual return; late ATL surcharge is Rs. 1,000 for individuals.', '15–25 minutes online (instant NTN certificate download)', 'FBR IRIS Online Portal & RTO Islamabad Facilitation Desk', 'Online via iris.fbr.gov.pk (Walk-in helpdesk: Regional Tax Office, Plot 20, Mauve Area, G-9/1, Islamabad)', 'Online Portal: 24/7 | RTO Helpdesk Mon–Fri: 9:00 AM – 3:30 PM', 'Complete online any weekday morning (OTP SMS arrives fastest before 12 PM)', 'https://iris.fbr.gov.pk/', '2026-11-16T07:00:00Z', TRUE, TRUE, 4) ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.processes (id, slug, title, urdu_title, summary, category, city, fee_normal, fee_urgent, fee_executive, fee_notes, time_required, office_name, office_address, office_timings, best_day_to_go, official_source_url, last_updated, is_verified, is_nationwide, popularity_rank) VALUES ('a1000000-0000-4000-8000-000000000005', 'domicile-certificate-rawalpindi', 'Domicile Certificate in Rawalpindi', 'ڈومیسائل سرٹیفکیٹ — راولپنڈی', 'Exact document list, e-Khidmat Markaz counter flow, and challan details for getting a computerized Punjab Domicile Certificate in Rawalpindi for university admission or government jobs.', 'Certificates', 'Rawalpindi', 500, 1000, 1500, 'Government treasury challan is Rs. 200 plus e-Khidmat processing/stamp paper cost (~Rs. 300 total = Rs. 500 Normal). Urgent/Executive figures reflect expedited facilitation & extra stamp affidavit if needed.', 'Normal: 10–15 working days | Urgent: 5 working days', 'e-Khidmat Markaz Rawalpindi', 'Liaquat Bagh Sports Complex, Main Murree Road, Rawalpindi', 'Mon–Sat: 9:00 AM – 5:00 PM (Break 1:00 PM – 2:00 PM; Closed Sun)', 'Wednesday morning around 9:15 AM (avoid university admission deadline weeks)', 'https://ekhidmat.punjab.gov.pk/', '2026-11-14T10:15:00Z', TRUE, FALSE, 5) ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.processes (id, slug, title, urdu_title, summary, category, city, fee_normal, fee_urgent, fee_executive, fee_notes, time_required, office_name, office_address, office_timings, best_day_to_go, official_source_url, last_updated, is_verified, is_nationwide, popularity_rank) VALUES ('a1000000-0000-4000-8000-000000000006', 'birth-certificate-rawalpindi', 'Birth Certificate in Rawalpindi', 'پیدائش کا سرٹیفکیٹ — راولپنڈی', 'How to get a computerized NADRA / Union Council Birth Registration Certificate (and subsequent B-Form/CRC) in Rawalpindi Municipal Corporation or Cantonment Board areas.', 'Certificates', 'Rawalpindi', 500, 1000, 1500, 'Standard timely registration (within 60 days of birth) at Union Council / e-Khidmat costs Rs. 300–500. Late registration (after 1 year) involves an extra magistrate/court affidavit and fee.', 'Normal: 7–10 working days | Urgent: 3–5 working days', 'Union Council / e-Khidmat Markaz & RCB Rawalpindi', 'e-Khidmat Markaz Liaquat Bagh, Murree Road (For Cantt residents: Rawalpindi Cantonment Board, The Mall, Saddar)', 'Mon–Fri: 9:00 AM – 3:30 PM | e-Khidmat Mon–Sat: 9:00 AM – 5:00 PM', 'Tuesday or Wednesday before 10:30 AM', 'https://lgcd.punjab.gov.pk/', '2026-11-13T14:00:00Z', TRUE, FALSE, 6) ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.processes (id, slug, title, urdu_title, summary, category, city, fee_normal, fee_urgent, fee_executive, fee_notes, time_required, office_name, office_address, office_timings, best_day_to_go, official_source_url, last_updated, is_verified, is_nationwide, popularity_rank) VALUES ('a1000000-0000-4000-8000-000000000007', 'police-character-certificate-rawalpindi', 'Police Character Certificate in Rawalpindi', 'پولیس کریکٹر سرٹیفکیٹ — راولپنڈی', 'Fast, clean walkthrough for obtaining a QR-verified Punjab Police Character Certificate for foreign visa, study abroad, immigration, or employment at Police Khidmat Markaz Rawalpindi.', 'Certificates', 'Rawalpindi', 500, 1000, 1500, 'Official Punjab Police Khidmat Markaz fee is Rs. 500 for standard verification. Overseas/urgent attestation or additional address verification may add Rs. 500–1,000.', '3 working days (SMS alert when ready for collection or online download)', 'Police Khidmat Markaz Rawalpindi', 'Police Khidmat Markaz, Near Liaquat Bagh / Commercial Market Satellite Town, Rawalpindi', 'Mon–Sat: 8:00 AM – 8:00 PM (Closed Sunday)', 'Wednesday or Thursday between 10:00 AM – 12:30 PM', 'https://pkm.punjab.gov.pk/', '2026-11-15T12:00:00Z', TRUE, FALSE, 7) ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.processes (id, slug, title, urdu_title, summary, category, city, fee_normal, fee_urgent, fee_executive, fee_notes, time_required, office_name, office_address, office_timings, best_day_to_go, official_source_url, last_updated, is_verified, is_nationwide, popularity_rank) VALUES ('a1000000-0000-4000-8000-000000000008', 'child-passport-under-18', 'Child Passport (Under 18) in Rawalpindi', 'بچوں کا پاسپورٹ (18 سال سے کم)', 'Everything parents need to know to apply for a newborn or minor (under 18) Pakistani passport in Rawalpindi using NADRA CRC (B-Form) or Smart Juvenile Card.', 'Passport', 'Rawalpindi', 4500, 7500, 12500, 'Children under 15 years are issued 5-year validity passports only (10-year option is for 15+ years). Fees shown are for a 36-page 5-year MRP.', 'Normal: 21 working days | Urgent: 5 working days | Fast Track: 2 working days', 'Regional Passport Office Rawalpindi (Family Counter)', 'Near Rehmanabad Chowk, Main Murree Road (Opposite Sixth Road Metro Station), Rawalpindi', 'Mon–Thu: 8:30 AM – 2:00 PM | Fri: 8:30 AM – 12:30 PM', 'Tuesday or Thursday at 8:15 AM (dedicated family lane moves faster early)', 'https://dgip.gov.pk/passport/minor-passport.php', '2026-11-14T16:30:00Z', TRUE, FALSE, 8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.processes (id, slug, title, urdu_title, summary, category, city, fee_normal, fee_urgent, fee_executive, fee_notes, time_required, office_name, office_address, office_timings, best_day_to_go, official_source_url, last_updated, is_verified, is_nationwide, popularity_rank) VALUES ('a1000000-0000-4000-8000-000000000009', 'name-change-cnic-after-marriage', 'Name Change on CNIC After Marriage', 'شادی کے بعد شناختی کارڈ میں نام کی تبدیلی', 'How to update marital status, add husband’s name, and optionally update surname on your Smart CNIC at NADRA Mega Center Rawalpindi with Computerized MRC.', 'Family', 'Rawalpindi', 750, 1500, 2500, 'Standard NADRA Smart CNIC modification fee (Rs. 750 Normal, Rs. 1,500 Urgent, Rs. 2,500 Executive). Both marital status update and name change can be done in the same single fee.', 'Normal: 31 days | Urgent: 15 days | Executive: 7 days', 'NADRA Mega Center Rawalpindi (Rehmanabad)', 'Ground Floor, Rehmanabad Plaza, Main Murree Road near Rehmanabad Metro Station, Rawalpindi', 'Mon–Sat: 8:00 AM – 8:00 PM (Dedicated ladies & family waiting area)', 'Tuesday or Wednesday at 9:00 AM (husband and wife should visit together)', 'https://www.nadra.gov.pk/identity/identity-cnic', '2026-11-15T11:20:00Z', TRUE, FALSE, 9) ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.processes (id, slug, title, urdu_title, summary, category, city, fee_normal, fee_urgent, fee_executive, fee_notes, time_required, office_name, office_address, office_timings, best_day_to_go, official_source_url, last_updated, is_verified, is_nationwide, popularity_rank) VALUES ('a1000000-0000-4000-8000-000000000010', 'e-challan-check-and-payment', 'E-Challan Check and Payment (PSCA / Traffic)', 'ای چالان چیک اور ادائیگی', 'Check pending Safe City camera e-Challans by vehicle number & CNIC and pay online in 2 minutes using PSID code via JazzCash, Easypaisa, or any Pakistani banking app.', 'Driving', 'Lahore', 200, 500, 2000, 'Traffic fines vary by violation: Rs. 200 (typical helmet/minor motorcycle violation), Rs. 500 (lane/seatbelt/standard car violation), up to Rs. 2,000 (red signal jump or overspeeding). Zero portal service fee via e-Pay Punjab.', '2–5 minutes online (instant digital receipt & PSCA clearance)', 'Punjab Safe Cities Authority (PSCA) E-Challan Portal', 'Online via echallan.psca.gop.pk (In-person dispute center: Qurban Lines, Jail Road, Lahore / Local Traffic HQ)', 'Online Check & Pay: 24/7 | Dispute Desk Mon–Sat: 9:00 AM – 4:00 PM', 'Pay online immediately within 10 days to avoid late-payment escalation', 'https://echallan.psca.gop.pk/', '2026-11-16T06:45:00Z', TRUE, TRUE, 10) ON CONFLICT (slug) DO NOTHING;
