INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1010000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000001', 'Paid Fee Challan / Passport Fee Asaan PSID Receipt', 'original', 1, 'Pay via Passport Fee Asaan app (1Link / JazzCash / Bank App) and bring printed SMS/PDF receipt — saves 45 minutes of NBP bank queue!', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1010000-0000-4000-8000-000000000006', 'a1000000-0000-4000-8000-000000000001', 'NOC from Department (Government Employees Only)', 'original', 1, 'Only required if you are a serving government/armed forces employee.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1020000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000002', 'Original Expired / Expiring CNIC (Purana Asal Card)', 'original', 1, 'If lost, bring an FIR/Police Roznamcha Lost Report instead.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1020000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000002', 'Photocopy of Old CNIC', 'photocopy', 1, 'Helpful to keep for your own record once NADRA punches the old card.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1020000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000002', 'Original CNIC of Any Blood Relative (Only if changing address)', 'original', 1, 'Not needed for simple renewal with no changes. Needed only if updating address or family tree.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1020000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000002', 'Utility Bill Copy (Only if updating present address)', 'photocopy', 1, 'Electricity, gas, or water bill showing your new Rawalpindi address.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1020000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000002', 'Active Mobile Phone (SIM registered on your CNIC)', 'original', 1, 'For receiving NADRA tracking token & SMS updates when your card is ready.', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1030000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000003', 'Original Valid CNIC (Asal Shanakhti Card)', 'original', 1, 'Must be valid for biometric verification at Traffic Police counter.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1030000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000003', 'Photocopy of CNIC (Front & Back)', 'photocopy', 2, 'Clear front and back copy on one sheet.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1030000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000003', 'Original Expired / Expiring Driving Licence', 'original', 1, 'Old PVC licence card must be surrendered at the counter.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1030000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000003', 'Photocopy of Previous Driving Licence', 'photocopy', 1, 'Keep one copy for your file and DLIMS licence number lookup.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1030000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000003', 'Medical Fitness Certificate (Form B — if age 50+)', 'original', 1, 'Required for applicants aged 50 or older (or LTV/HTV renewals). Available from authorized medical officer inside Traffic HQ.', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1030000-0000-4000-8000-000000000006', 'a1000000-0000-4000-8000-000000000003', 'Passport-Size Photos (Blue/White Background)', 'original', 2, 'Live photo is captured at the counter, but carry 2 backup photos for manual medical form if needed.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1040000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000004', 'Original CNIC (13-digit CNIC Number)', 'original', 1, 'Your CNIC number becomes your NTN in Pakistan. Keep it handy to type accurately.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1040000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000004', 'Mobile SIM Registered in Your Own Name (Apne Naam ki SIM)', 'original', 1, 'CRITICAL: FBR IRIS rejects SIMs registered on a parent or spouse CNIC.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1040000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000004', 'Active Personal Email Address', 'original', 1, 'You will receive a separate 6-digit email verification OTP alongside your SMS OTP.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1040000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000004', 'Recent Electricity Bill Copy (24-digit Meter/Reference Number)', 'photocopy', 1, 'Needed to fill residential address / utility meter field in your IRIS Form 181 profile.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1040000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000004', 'Personal Bank Account IBAN', 'photocopy', 1, 'Required if you also want to add your freelance bank account and business name in IRIS.', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1050000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000005', 'Original CNIC or NADRA B-Form (if under 18)', 'original', 1, 'Permanent OR present address on CNIC should be in District Rawalpindi.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1050000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000005', 'Photocopy of Applicant CNIC & Father’s CNIC', 'photocopy', 2, 'Two clear sets of front & back copies (attested by Grade 17 officer if applying manually).', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1050000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000005', 'Utility Bill Proof of Rawalpindi Residence', 'photocopy', 2, 'Recent IESCO electricity or SNGPL gas bill (or registered rent agreement) showing Rawalpindi address.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1050000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000005', 'Matric / Educational Certificate Copy', 'photocopy', 1, 'School/Matric certificate or student card to verify date of birth and Rawalpindi residence.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1050000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000005', 'Affidavit on Rs. 100 Stamp Paper (Bayan-e-Halfi)', 'original', 1, 'Stating you do not hold a domicile from any other district of Pakistan, attested by Oath Commissioner.', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1050000-0000-4000-8000-000000000006', 'a1000000-0000-4000-8000-000000000005', 'Passport-Size Photos (Blue Background)', 'original', 3, '3 recent clear photographs without cap or sunglasses.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1050000-0000-4000-8000-000000000007', 'a1000000-0000-4000-8000-000000000005', 'Domicile Challan Form 32-A (Rs. 200 NBP / e-Pay)', 'original', 1, 'Pay via e-Pay Punjab app or NBP branch and attach original paid receipt.', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1060000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000006', 'Hospital Birth Slip / Vaccination Card (Original)', 'original', 1, 'Signed & stamped discharge/birth slip from hospital (or Lady Health Worker card for home birth).', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1060000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000006', 'Photocopy of Hospital Birth Slip', 'photocopy', 2, 'Attach two clear copies to the Union Council application.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1060000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000006', 'Father & Mother Original CNICs', 'original', 1, 'Both parents’ CNICs must be valid; mother’s CNIC should preferably reflect married status.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1060000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000006', 'Photocopies of Parents’ CNICs & Grandfather’s CNIC', 'photocopy', 2, 'Front and back copies of father, mother, and paternal grandfather (if available).', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1060000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000006', 'Computerized Nikahnama / NADRA MRC Copy', 'photocopy', 1, 'Required by Union Council to confirm parents’ marriage record.', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1060000-0000-4000-8000-000000000006', 'a1000000-0000-4000-8000-000000000006', 'Late Registration Affidavit (Only if child is older than 60 days)', 'original', 1, 'Rs. 100 stamp paper affidavit attested by Oath Commissioner (for births > 1 year old, court order/ADLG permission may be needed).', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1070000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000007', 'Original Valid CNIC (or B-Form if under 18)', 'original', 1, 'Required for live biometric and NADRA record check.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1070000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000007', 'Photocopy of CNIC (Front & Back)', 'photocopy', 2, 'Two clear photocopies on A4 sheet.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1070000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000007', 'Original Passport & Bio-data Page Copy', 'photocopy', 1, 'Mandatory if applying for foreign visa, study abroad, or immigration — passport number is printed on the certificate.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1070000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000007', 'Proof of Rawalpindi Address (Utility Bill or Rent Agreement)', 'photocopy', 1, 'Needed if your CNIC permanent address is outside Rawalpindi and you want verification for your Rawalpindi stay period.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1070000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000007', 'Authority Letter (Only if blood relative is applying for overseas Pakistani)', 'original', 1, 'Required only when applicant is abroad and a father/brother/spouse applies on their behalf.', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1080000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000008', 'Original NADRA CRC (B-Form) or Smart Juvenile Card', 'original', 1, 'Must be computerized NADRA CRC with 13-digit number (for ages 10–18, Smart Juvenile Card or CRC with child’s photo is strongly preferred).', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1080000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000008', 'Photocopy of NADRA B-Form / CRC', 'photocopy', 2, 'Check that child’s name spelling matches birth certificate & school record exactly.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1080000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000008', 'Original Valid CNICs of Both Father and Mother', 'original', 1, 'At least one parent must accompany the child with both parents’ original CNICs (both parents recommended to avoid consent form delays).', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1080000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000008', 'Photocopies of Both Parents’ CNICs', 'photocopy', 2, 'Front and back copies of father’s and mother’s CNICs.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1080000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000008', 'Paid Fee Challan / Passport Fee Asaan Receipt', 'original', 1, 'Generate PSID against the child’s 13-digit B-Form number, NOT the father’s CNIC!', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1080000-0000-4000-8000-000000000006', 'a1000000-0000-4000-8000-000000000008', 'Previous Passport (If renewing child passport)', 'original', 1, 'Only required if the child already held a Pakistani passport earlier.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1090000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000009', 'Original Wife’s Existing CNIC', 'original', 1, 'Will be updated to married status with husband’s name.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1090000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000009', 'Original Computerized NADRA Marriage Registration Certificate (MRC)', 'original', 1, 'Handwritten green Nikahnama alone is NO LONGER sufficient — get computerized MRC from your Union Council first!', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1090000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000009', 'Photocopy of Computerized MRC & Nikahnama', 'photocopy', 1, 'Keep one photocopy for counter attachment.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1090000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000009', 'Husband’s Original CNIC (Plus Physical Presence for Biometrics)', 'original', 1, 'Husband must accompany wife for live thumbprint verification. If husband is abroad, an attested undertaking/affidavit is needed.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1090000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000009', 'Photocopy of Husband’s CNIC', 'photocopy', 1, 'Front and back copy.', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1100000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000010', 'Vehicle Registration Number (Number Plate)', 'original', 1, 'Example: LEA-1234 or RIL-4567 (from your Excise Smart Card or registration book).', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1100000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000010', 'Vehicle Owner’s 13-Digit CNIC Number', 'original', 1, 'Must match the CNIC registered on Excise & Taxation record for that vehicle.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1100000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000010', 'Active Banking App, JazzCash, or Easypaisa Account', 'original', 1, 'Used to pay the 17-digit PSID code under Government Payments → e-Pay Punjab / PSCA.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1100000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000010', 'Printed / Saved E-Challan Payment Receipt (PDF Screenshot)', 'photocopy', 1, 'Save digital confirmation receipt on your phone in case a traffic warden checks.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1010000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000001', 1, 'Pay Fee Online Before Leaving Home (Passport Fee Asaan)', 'Download the official "Passport Fee Asaan" app by DGIP, select Passport Renewal (36 pages, 5 or 10 years, Normal/Urgent/Fast Track), enter your CNIC, and generate a PSID code. Pay via JazzCash, Easypaisa, or any Pakistani bank app and print the confirmation receipt.', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1010000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000001', 2, 'Entry Gate Verification & Token Counter', 'Arrive at Regional Passport Office Rawalpindi near Rehmanabad by 8:00 AM. Show your original CNIC, old passport, and printed fee receipt at the gate to collect your numbered token slip.', 20) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1010000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000001', 3, 'Biometrics & Live Photograph Counter', 'When your token appears on the screen, proceed to the Biometrics booth. The operator captures your fingerprints and live passport photo (do not wear a white shirt — dark/medium collar looks best against the white backdrop).', 15) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1010000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000001', 4, 'Data Entry & Draft Review', 'Move to the Data Entry counter. The officer pulls your NADRA data and prints a draft verification sheet. Carefully check spelling of your name, father’s name, date of birth, and CNIC before signing — errors after printing cost a full new fee.', 15) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1010000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000001', 5, 'Assistant Director (AD) Final Verification Interview', 'Wait for your token at the Assistant Director desk. The officer verifies your old passport, punches it as cancelled (leaving valid visas uncut), approves your renewal in the system, and hands you the collection token.', 20) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1010000-0000-4000-8000-000000000006', 'a1000000-0000-4000-8000-000000000001', 6, 'Track SMS & Collect New Passport', 'Watch for the SMS from 9988 when your passport is ready (21 working days Normal, 5 Urgent, 2 Fast Track). Bring your original CNIC, cancelled old passport, and original token slip to the Delivery Window for collection.', 15) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1020000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000002', 1, 'Enter NADRA Mega Center & Collect Token', 'Walk into NADRA Mega Center Rehmanabad (main entrance on Murree Road). Show your old CNIC at the reception desk and select Normal, Urgent, or Executive service to receive a queue token.', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1020000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000002', 2, 'Wait in Hall & Watch Token Screen', 'Wait in the air-conditioned hall until your token number is called. Senior citizens, pregnant women, and persons with disabilities have priority counters.', 25) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1020000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000002', 3, 'Photo, Fingerprints & Signature Capture', 'At the Data Entry Operator (DEO) counter, your fresh photograph, four-finger + thumbprints, and digital signature are captured. No paper form filling is needed.', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1020000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000002', 4, 'Verify Printed Form & Pay Fee at Counter', 'Carefully check your English and Urdu name spellings, address, and date of birth on the printed summary sheet. Pay the exact fee (Rs. 750 / 1,500 / 2,500) directly at the NADRA fee counter by cash or card and keep the tracking receipt.', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1020000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000002', 5, 'Receive SMS Alert & Collect Smart CNIC', 'NADRA sends an SMS from 8400 once your Smart Card arrives at the center (or dispatches by courier if opted). Visit the Delivery Counter with your original token slip and old CNIC to collect.', 15) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1030000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000003', 1, 'Check Licence Record on DLIMS Portal First', 'Before visiting, check your existing licence number on dlims.punjab.gov.pk/track to confirm your record is digitized. If you want to skip lines completely, you can also start renewal online on DLIMS 2.0.', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1030000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000003', 2, 'Arrive at Traffic HQ Race Course & Get Token', 'Enter the Licensing Branch at Race Course Ground, Peshawar Road. Show your original CNIC and expired licence at the inquiry booth to collect a Renewal Token.', 15) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1030000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000003', 3, 'Pay Fee Ticket / e-Pay PSID Challan', 'Purchase the renewal fee ticket or pay the generated PSID code via JazzCash / Bank App right at the licensing center. Choose 1-year, 3-year, or 5-year validity.', 15) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1030000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000003', 4, 'Medical Check (Only if 50+ or Commercial LTV/HTV)', 'Applicants under 50 renewing a private car/motorcycle licence do NOT need a driving test or medical exam. If aged 50+, visit the on-site medical room for a quick eyesight check.', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1030000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000003', 5, 'Biometric Capture & Live Photo at DLIMS Counter', 'Hand over your old licence and CNIC at the DLIMS booth. Your photo and thumbprints are updated and a digital renewal receipt is printed immediately.', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1030000-0000-4000-8000-000000000006', 'a1000000-0000-4000-8000-000000000003', 6, 'Download E-Licence Instantly & Receive PVC Card', 'Within hours, download your legal QR-verified e-Licence PDF from dlims.punjab.gov.pk. The physical PVC card is dispatched to your Rawalpindi address via Pakistan Post within 7–15 days.', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1040000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000004', 1, 'Open Official FBR IRIS 2.0 Portal', 'Visit iris.fbr.gov.pk on your phone or laptop and click "New Registration" at the bottom of the login card. Ignore third-party agent websites charging Rs. 3,000+.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1040000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000004', 2, 'Enter CNIC, Own-Name Mobile Number & Email', 'Type your 13-digit CNIC without dashes, full name as on CNIC, select your mobile network operator (Jazz, Zong, Telenor, Ufone), enter your mobile number in 00923xxxxxxxxx format, and your personal email.', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1040000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000004', 3, 'Verify Both SMS & Email OTP Codes', 'FBR sends two separate 6-digit codes — one to your SMS and one to your email inbox. Enter both codes carefully and submit to receive your IRIS Password and 4-digit PIN via SMS/Email.', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1040000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000004', 4, 'Log In to IRIS & Add Freelance Business Profile (Form 181)', 'Sign in with your CNIC and new password. Go to Registration → 181 (Form of Registration filed voluntarily), add your residential address, bank IBAN, and freelance IT/Software Export activity (Code 6201 / 6209 for PSEB 0.25% rate eligibility).', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1040000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000004', 5, 'Download Official Taxpayer Registration Certificate (NTN)', 'From the left menu, open "Completed Tasks" → click your 181 Registration Order → click Print/Download PDF. You can also verify your NTN instantly on FBR’s Online Taxpayer Verification page.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1050000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000005', 1, 'Prepare Stamp Paper Affidavit & Pay Rs. 200 Challan', 'Get a Rs. 100 stamp paper affidavit (Bayan-e-Halfi) stating you have no domicile from another district, attested by an Oath Commissioner (easily available outside District Courts / Kachehri or near Liaquat Bagh). Pay the Rs. 200 Domicile Fee via e-Pay Punjab or NBP Form 32-A.', 25) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1050000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000005', 2, 'Visit e-Khidmat Markaz Liaquat Bagh & Collect Token', 'Go to e-Khidmat Markaz inside Liaquat Bagh Sports Complex on Murree Road. Show your complete document folder at the reception desk to get a Domicile Token.', 15) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1050000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000005', 3, 'Document Scrutiny & Data Entry Counter', 'At the Domicile counter, the officer scans your CNIC, utility bill, affidavit, and Matric certificate, captures your live photo, and enters your Form P/P-1 details into the Punjab Domicile Management System.', 15) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1050000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000005', 4, 'Receive Tracking Receipt & Wait for Patwari/DC Verification', 'Collect your computerized tracking receipt with SMS tracking number. The Deputy Commissioner office verifies your Rawalpindi residence record digitally (takes 10–15 working days).', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1050000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000005', 5, 'Collect Signed QR-Verified Domicile Certificate', 'Once you receive the readiness SMS, return to the e-Khidmat delivery window with your original CNIC and tracking slip to collect your official Domicile Certificate.', 15) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1060000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000006', 1, 'Identify Your Exact Union Council or Cantonment Ward', 'Check your home address or father’s CNIC to see whether you fall under Rawalpindi Municipal Corporation (Union Council / e-Khidmat Markaz Liaquat Bagh) or Rawalpindi Cantonment Board (RCB Saddar) or Chaklala Cantonment Board (CCB).', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1060000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000006', 2, 'Collect & Fill Birth Registration Form (CRMS)', 'Obtain the official Birth Registration Form at the Union Council Secretary desk or e-Khidmat counter. Fill in the child’s exact English & Urdu name, date/place of birth, and parents’ CNIC numbers clearly.', 15) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1060000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000006', 3, 'Submit Documents & Pay Official Fee', 'Attach the hospital birth slip, copies of parents’ CNICs, and Nikahnama/MRC copy. Pay the Rs. 300–500 registration fee at the fee counter and keep the official stamped receipt.', 20) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1060000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000006', 4, 'Union Council Verification & CRMS Entry', 'The UC Secretary verifies the hospital slip and enters the child’s record into the NADRA Civil Registration Management System (CRMS). This takes 5–10 working days.', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1060000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000006', 5, 'Collect Computerized Birth Certificate & Apply for B-Form', 'Collect the printed NADRA-format computerized Birth Certificate bearing the UC Secretary’s stamp and QR code. Double-check every spelling before leaving — you will use this certificate at NADRA to get the child’s B-Form (CRC).', 15) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1070000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000007', 1, 'Book Optional Online Appointment (PKM App) or Walk In', 'Download the "Punjab Police Khidmat" app (or visit pkm.punjab.gov.pk) to pre-book a time slot at Police Khidmat Markaz Liaquat Bagh or Commercial Market Satellite Town. Walk-ins are also welcome.', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1070000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000007', 2, 'Collect Token & Confirm Stay Dates', 'At the Khidmat Markaz reception, show your original CNIC and passport copy. Confirm the exact start and end dates of your stay in Rawalpindi that need to appear on the certificate.', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1070000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000007', 3, 'Live Photo, Biometrics & Data Entry', 'At the counter, the staff takes your live photograph and thumbprints, checks PSRMS (Police Station Record Management System), and scans your CNIC & passport.', 15) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1070000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000007', 4, 'Pay Rs. 500 Fee & Get Computerized Receipt', 'Pay the official Rs. 500 fee at the counter and receive your printed slip with tracking number and collection date (typically 3 working days).', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1070000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000007', 5, 'Collect Certificate or Download Digital Copy', 'After local police station digital clearance (3 working days), collect your signed QR-verified certificate from the counter with your receipt — or verify/download it from the PKM portal for MOFA attestation.', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1080000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000008', 1, 'Pay Fee Against Child’s 13-Digit B-Form Number', 'Open the "Passport Fee Asaan" app, choose New Passport (36 pages, 5-year validity for under 15), and carefully enter the CHILD’S 13-digit NADRA CRC/B-Form number — never the parent’s CNIC. Pay via mobile banking and print the receipt.', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1080000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000008', 2, 'Arrive With Child & Both Parents’ Original CNICs', 'Bring the child physically (even newborns must appear for live photo!) along with original B-Form/CRC, both parents’ original CNICs, and the printed fee receipt to Regional Passport Office Rawalpindi.', 20) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1080000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000008', 3, 'Get Family Counter Token', 'Show the documents at the reception to receive a Family/Child priority token.', 15) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1080000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000008', 4, 'Child’s Live Photo & Parent Biometric Consent', 'At the Photo/Biometrics booth, the child’s photograph is captured (tip: bring a light-colored toy or feed infants beforehand so they look straight at the camera). The accompanying parent gives biometric thumbprint verification.', 15) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1080000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000008', 5, 'Data Entry & Assistant Director Sign-Off', 'Check the draft print carefully — make sure the child’s name spelling matches the B-Form and parents’ passports. Proceed to the AD desk for final approval and collect your delivery token.', 20) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1080000-0000-4000-8000-000000000006', 'a1000000-0000-4000-8000-000000000008', 6, 'Collect Child’s Passport on SMS Confirmation', 'Either parent can collect the passport using their original CNIC, child’s original B-Form, and the original collection token once the 9988 readiness SMS arrives.', 15) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1090000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000009', 1, 'Get Computerized NADRA MRC From Union Council First', 'Before going to NADRA, register your handwritten Nikahnama at the Union Council where the Nikah took place and collect the Computerized Marriage Registration Certificate (MRC). NADRA requires the MRC QR record.', 15) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1090000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000009', 2, 'Visit NADRA Mega Center Together (Wife & Husband)', 'Both husband and wife visit NADRA Mega Center Rehmanabad with both original CNICs and the original Computerized MRC. Request a "CNIC Modification" token at the desk.', 15) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1090000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000009', 3, 'Photo Capture, Husband’s Biometric Attestation & Data Entry', 'At the counter, tell the operator clearly whether you only want to change Father’s Name to Husband’s Name (keeping your maiden surname) OR also adopt your husband’s surname. Husband provides live biometric verification right at the counter.', 15) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1090000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000009', 4, 'Double-Check Draft Print & Pay Modification Fee', 'Carefully verify English & Urdu spellings of your updated name, husband’s name, and new address (if changing). Pay Rs. 750 (Normal), Rs. 1,500 (Urgent), or Rs. 2,500 (Executive) and keep the receipt.', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1090000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000009', 5, 'Collect Updated Smart CNIC', 'Wait for the SMS from 8400 and collect your updated Smart CNIC from the delivery counter (or home delivery). Remember to also update your passport & bank records if you changed your surname.', 15) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1100000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000010', 1, 'Open Official PSCA E-Challan Portal', 'Go to echallan.psca.gop.pk on your mobile browser (or open the "e-Pay Punjab" app). For Islamabad Safe City e-Challans, use the ITP portal.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1100000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000010', 2, 'Enter Vehicle Registration Number & Owner CNIC', 'Type your vehicle plate number (e.g., LEA-1234) and the vehicle owner’s 13-digit CNIC number, complete the captcha, and click Search.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1100000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000010', 3, 'Verify Camera Evidence Photo & Copy 17-Digit PSID', 'Review the violation date, location, and traffic camera photos to make sure it is actually your vehicle (not a fake/cloned number plate). Download the challan PDF and copy the 17-digit PSID payment number.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1100000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000010', 4, 'Pay Instantly via JazzCash, Easypaisa, or Bank App', 'Open your banking app (HBL, Meezan, UBL, SadaPay, JazzCash, Easypaisa) → Government Payments / 1Bill → GoPb / e-Pay Punjab → paste the 17-digit PSID. Verify the fine amount and owner name, then confirm payment.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1100000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000010', 5, 'Confirm "Paid" Status & Save Receipt', 'Refresh echallan.psca.gop.pk after 2 minutes to confirm the challan status shows "Paid". Save a screenshot of the paid receipt on your phone.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11010000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000001', 'Going to NBP Bank Without Checking Passport Fee Asaan App', 'Standing in the National Bank queue outside the Passport Office wastes 45–90 minutes. Paying online via the official Passport Fee Asaan app takes 5 minutes from home and is accepted at every counter.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11010000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000001', 'Arriving With an Expired CNIC or Wearing White Clothes', 'If your CNIC is even 1 day expired, the Passport system blocks your application immediately. Also avoid wearing a pure white shirt/dupatta as it blends with the white photo screen and causes rejection.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11010000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000001', 'Not Proofreading the Data Entry Draft Sheet', 'Once you sign the draft slip, even a single wrong letter in your name or birthplace requires paying a brand-new modification fee. Read every single letter slowly before signing.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11020000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000002', 'Going on Monday Morning Instead of Mid-Week Afternoon', 'Monday 8 AM – 12 PM has the longest queues of the entire week at Rehmanabad Mega Center (often 2+ hours). Wednesday or Thursday afternoon cuts waiting time in half.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11020000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000002', 'Trying to Change Address Without Bringing a Utility Bill', 'Simple renewal needs only your old CNIC, but if you also ask the operator to update your address, they will turn you back without a utility bill or blood relative’s CNIC bearing that address.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11020000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000002', 'Paying Touts Outside the Gate for "Fast Token"', 'Agents standing outside NADRA charge Rs. 1,000–2,000 extra for nothing — all tokens are issued strictly on CNIC inside the hall, and Executive tier is officially Rs. 2,500 at the counter.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11030000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000003', 'Waiting Over 3 Years After Expiry (Triggers Fresh Driving Test)', 'Renewing on time or within the grace window requires zero driving test. Letting your licence stay expired for years triggers late penalties and can require repeating the learner & road test.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11030000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000003', 'Forgetting Medical Certificate When Age is 50+', 'Applicants aged 50 or above (or holding LTV/HTV) cannot pass the counter without Form B medical fitness clearance. Check your age requirement before queuing.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11030000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000003', 'Not Carrying Your Original Expired Card', 'A photocopy or mobile photo of your old driving licence is not accepted at the renewal counter unless you bring an official Police Lost Report (e-Gadget/Roznamcha) for a duplicate.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11040000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000004', 'Using a SIM Registered in Father’s or Brother’s Name', 'IRIS cross-checks PTA records automatically. If the mobile SIM is not registered against your own CNIC, registration fails immediately with an error.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11040000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000004', 'Thinking NTN Alone Makes You a "Filer" (ATL)', 'Getting an NTN only registers you in FBR. To enjoy lower Filer withholding tax rates on bank transfers and vehicles, you must also file your annual Income Tax Return on IRIS.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11040000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000004', 'Leaving Business Activity Blank (Missing 0.25% IT Export Rate)', 'Freelancers earning foreign IT remittances via bank PRC qualify for 0.25% final tax (with PSEB registration) — make sure you add IT/Software Consultancy activity in Form 181.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11050000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000005', 'Arriving Without an Oath Commissioner Attested Affidavit', 'e-Khidmat counters will not accept your file without the Rs. 100 stamp paper Bayan-e-Halfi signed by an Oath Commissioner. Get it ready before going inside Liaquat Bagh.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11050000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000005', 'CNIC Has Neither Permanent Nor Present Address in Rawalpindi', 'If both addresses on your CNIC belong to another district, your Rawalpindi domicile will be rejected unless you first update your CNIC address or show strong tenancy/residence proof plus NOC.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11050000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000005', 'Applying 2 Days Before University Admission Deadline', 'Domicile verification takes 10–15 working days and cannot be issued on the same day. Apply at least 3 weeks before MDCAT, ECAT, or university deadlines.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11060000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000006', 'Going to Municipal Union Council When You Live in Cantt Area', 'Rawalpindi Cantonment (Saddar, Westridge, Peshawar Road) and Chaklala Cantt (Scheme III, Gulraiz) residents must apply at RCB/CCB offices, NOT city Union Councils.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11060000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000006', 'Misspelled Child Name on Birth Certificate vs Future Passport', 'Whatever English spelling is printed on the UC Birth Certificate gets copied onto the NADRA B-Form and later the child’s Passport. Double-check spellings carefully before final printing.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11060000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000006', 'Delaying Registration Beyond 60 Days Without Realizing Late Rules', 'Registering within 60 days is simple and cheap. Waiting over 1 year adds affidavits, witnesses, and Assistant Director Local Government (ADLG) approval steps that waste weeks.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11070000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000007', 'Applying Without Passport Copy When Needed for Visa/Study', 'Embassies require your exact Passport Number printed on the Police Character Certificate. If you apply with only your CNIC, the certificate will omit the passport number and embassies may reject it.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11070000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000007', 'Entering Wrong Stay Period Dates', 'Check your embassy checklist (usually requires last 5 or 10 years of stay). If your stay dates leave a gap or overlap incorrectly, you will have to pay and re-apply.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11070000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000007', 'Not Leaving Time for MOFA Attestation', 'Police Character Certificate takes 3 working days — if your visa requires Ministry of Foreign Affairs (MOFA) attestation in Islamabad, budget an extra 1–2 days after collection.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11080000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000008', 'Paying the Fee Challan Against Father’s CNIC Instead of Child’s B-Form', 'This is the #1 day-wasting mistake! Always enter the CHILD’S 13-digit NADRA B-Form/CRC number in Passport Fee Asaan. A challan paid on a parent’s CNIC cannot be linked to the child’s application.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11080000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000008', 'Leaving the Baby at Home Thinking Only Documents Are Needed', 'Even a 1-month-old infant MUST be physically present at the Passport Office for live photograph capture — external studio photographs are not accepted.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11080000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000008', 'Bringing Only One Parent’s CNIC Without the Other Parent’s Original CNIC', 'Even if only one parent accompanies the child, the counter checks BOTH father’s and mother’s original valid CNICs (plus guardianship/custody documents if divorced or widowed).', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11090000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000009', 'Bringing Only the Handwritten Green Nikahnama', 'NADRA centers require the Computerized NADRA Marriage Registration Certificate (MRC) issued by your Union Council. Going with only the handwritten Nikahnama results in instant turnaround.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11090000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000009', 'Going Without Husband for Biometric Verification', 'Your husband must physically attend to verify his thumbprint on the NADRA scanner. If he is overseas, you need a Pakistan Embassy-attested affidavit/undertaking first.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11090000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000009', 'Changing Surname Without Checking Degrees & Existing Visas', 'You do NOT have to change your surname in Pakistan — you can keep your maiden name while updating your Father’s Name field to Husband’s Name. Changing your surname means updating your passport, degrees, and bank accounts too.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11100000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000010', 'Paying Before Checking the Camera Evidence Photos', 'Sometimes look-alike or fake number plates trigger wrongful e-Challans. Always inspect the 3 camera snapshots on echallan.psca.gop.pk before paying — you can dispute a wrong vehicle photo free of cost.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11100000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000010', 'Ignoring Unpaid E-Challans on a Car You Sold Without Transfer', 'Until the buyer completes biometric vehicle transfer at Excise & Taxation, all camera e-Challans remain tied to the previous owner’s CNIC and can block future vehicle or licence services.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11100000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000010', 'Entering Wrong Prefix/Dashes in Vehicle Plate Number', 'If a search shows "No Record Found", try both formats (with dash like LEA-1234 and with space/year format like LEA-18-1234) and double-check that you used the registered owner’s CNIC.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1010000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000001', 'Can I renew my Pakistani passport completely online without visiting the office?', 'Yes! If your passport has less than 7 months remaining (or is expired) and you want no data changes, you can apply via DGIP’s e-Services portal (onlinemrp.dgip.gov.pk) with fingerprint form upload and home courier delivery. However, many Rawalpindi residents still prefer walking into Rehmanabad RPO for faster Fast Track (2 working days) processing.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1010000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000001', 'What happens to valid US, UK, or Schengen visas in my old passport?', 'When the Assistant Director cancels your old passport, they punch only the cover and bio-data pages — NEVER the valid visa pages. Keep your old cancelled passport clipped together with your new passport when travelling.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1010000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000001', 'Should I choose the 5-year or 10-year passport validity?', 'For adults (15+ years), the 10-year 36-page passport (Rs. 6,700 Normal / Rs. 11,200 Urgent) saves you a whole extra office visit and costs significantly less per year than renewing every 5 years.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1010000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000001', 'Can someone else collect my renewed passport for me?', 'A blood relative (father, mother, sibling, spouse, or adult child) can usually collect it with their original CNIC, your original token slip, and an authority letter — though policies can tighten, so carrying your own CNIC is safest.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1010000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000001', 'How do I check if my passport is ready before going to the office?', 'SMS your 11-digit tracking token number (printed on your receipt) to 9988, or wait for the automated readiness SMS from 9988 before visiting the Delivery Window.', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1020000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000002', 'Can I renew my CNIC from home using the Pak-ID mobile app?', 'Yes! Download the official NADRA Pak-ID app on iOS/Android to renew your CNIC from home with phone-camera biometrics and home delivery. If your fingerprints fail to scan on phone, visit NADRA Mega Center Rehmanabad in person.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1020000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000002', 'Is there any late fine if my CNIC expired months ago?', 'No, NADRA does not charge a late expiry penalty for renewing an expired CNIC. You pay the standard Normal (Rs. 750), Urgent (Rs. 1,500), or Executive (Rs. 2,500) Smart Card fee.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1020000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000002', 'Is NADRA Mega Center Rehmanabad open on Saturday?', 'Yes! Unlike smaller tehsil centers, NADRA Mega Center Rehmanabad operates Monday through Saturday from 8:00 AM to 8:00 PM (closed on Sunday and public holidays).', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1020000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000002', 'Do I get a paper slip I can use while waiting for the new card?', 'Yes, NADRA gives you an official computerized token receipt (with photo and tracking ID) that serves as temporary proof of renewal for most local verifications until your Smart Card arrives.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1020000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000002', 'How can I track my CNIC delivery status?', 'Send your 12-digit Tracking ID via SMS to 8400 (standard SMS charges apply) to get an instant status update.', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1030000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000003', 'Do I have to give the driving test again when renewing my licence?', 'No! Standard renewal of a valid or recently expired driving licence in Punjab does NOT require a sign test or practical driving test. Only biometric verification and fee payment are needed.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1030000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000003', 'Can I renew my Punjab driving licence online without visiting Race Course Ground?', 'Yes! If your previous licence is already in the Punjab DLIMS digital database, you can log in at dlims.punjab.gov.pk, upload your photo/documents, pay the PSID via JazzCash/bank app, and download your e-Licence online.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1030000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000003', 'Is the digital e-Licence PDF legally accepted by Traffic Wardens?', 'Yes! Punjab Traffic Police officially recognize the QR-coded e-Licence PDF downloaded from DLIMS while you wait for your physical PVC card to arrive by post.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1030000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000003', 'Can I renew my licence for 5 years at once instead of 1 year?', 'Yes, Punjab DLIMS offers 1-year, 2-year, 3-year, and 5-year renewal options. Selecting 3 or 5 years saves you annual visits and protects against future fee revisions.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1030000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000003', 'Can I renew a Rawalpindi driving licence at e-Khidmat Markaz Liaquat Bagh?', 'Yes, Police Khidmat Markaz counters at Liaquat Bagh and Commercial Market Satellite Town also process driving licence renewals with evening timings till 8:00 PM.', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1040000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000004', 'Does registering for an FBR NTN cost any money?', 'No, NTN registration on iris.fbr.gov.pk is 100% free (Rs. 0). You do not need to pay any lawyer or consultant just to generate your NTN.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1040000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000004', 'What is the income tax rate for IT freelancers in Pakistan?', 'Export of IT and IT-enabled services (software development, design, freelancing paid in foreign currency through banking channels with PRC code 9186) is taxed at just 0.25% if registered with PSEB, or 1% without PSEB registration.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1040000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000004', 'Once I have an NTN, do I have to file a tax return every year?', 'Yes. Once registered on FBR IRIS, you should file your annual Income Tax Return (even if your income is below the taxable threshold) before the September 30 deadline each year to remain on the Active Taxpayer List (ATL).', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1040000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000004', 'Why am I not receiving the FBR SMS verification code?', 'Check three things: (1) the SIM is registered on your own CNIC, (2) you selected your current network operator accurately (ported/MNP numbers sometimes fail — try your original operator or visit RTO desk), and (3) your inbox isn’t blocking promotional SMS.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1040000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000004', 'Can I register my freelance business name on the same NTN?', 'Yes! Inside IRIS → Registration → Form 181, you can add your freelance studio or sole-proprietorship business name, business address, and bank account completely free.', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1050000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000005', 'Who is eligible to apply for a Rawalpindi Domicile Certificate?', 'Any Pakistani citizen residing in District Rawalpindi (with Rawalpindi address on CNIC/B-Form, utility bill, or verified continuous residence) who does not already hold a domicile from another district.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1050000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000005', 'Does a Domicile Certificate ever expire?', 'No, a Pakistan Domicile Certificate is valid for life unless you voluntarily cancel it to obtain a domicile in another district.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1050000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000005', 'Can a student under 18 apply for a Domicile without a CNIC?', 'Yes! Applicants under 18 can apply using their computerized NADRA B-Form (CRC) along with their father’s valid CNIC and Rawalpindi residence proof.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1050000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000005', 'Where do I get the Rs. 100 stamp paper affidavit near e-Khidmat Markaz?', 'Licensed stamp vendors and Oath Commissioners sit outside District Courts (Kachehri Chowk) and near Liaquat Bagh. Keep Rs. 200–300 cash for the stamp paper, typing, and Oath Commissioner stamp.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1050000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000005', 'How can I check if my Rawalpindi Domicile is genuine and ready?', 'Visit ekhidmat.punjab.gov.pk and enter your tracking ID to check live progress. Every new computerized domicile also carries a QR code for instant online verification.', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1060000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000006', 'What is the difference between a Birth Certificate and a NADRA B-Form (CRC)?', 'First, you get the computerized Birth Certificate from your local Union Council or Cantonment Board. Second, you take that Birth Certificate to NADRA to register the child in your family tree and get the 13-digit B-Form (CRC).', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1060000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000006', 'Can I apply for a Birth Certificate if the baby was born at home?', 'Yes, bring the child’s vaccination card from a government health center or a certificate from the Lady Health Worker (LHW) / Dai along with an affidavit on Rs. 100 stamp paper.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1060000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000006', 'What if the child was born in an Islamabad hospital but we live in Rawalpindi?', 'You can register the birth either in the Union Council where the hospital is located OR in your residential Rawalpindi Union Council using the original hospital birth slip and parents’ Rawalpindi CNICs.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1060000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000006', 'How do I get a Birth Certificate for an adult who never had one?', 'Adults apply under Late Birth Registration by submitting their CNIC, Matric certificate, parents’ CNICs, a Rs. 100 stamp paper affidavit, and obtaining ADLG / Magistrate approval before UC issuance.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1060000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000006', 'Does the Rawalpindi Birth Certificate work for foreign visas and MOFA attestation?', 'Yes! Computerized NADRA-format CRMS Birth Certificates issued by Punjab Union Councils and Cantonment Boards are accepted by MOFA Islamabad and foreign embassies.', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1070000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000007', 'How long is a Punjab Police Character Certificate valid?', 'Most embassies and employers accept a Police Character Certificate for 3 to 6 months from the date of issuance, though the certificate itself states the verified stay dates.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1070000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000007', 'Do I have to visit my local Thana (Police Station) personally?', 'No! Police Khidmat Markaz sends the verification digitally to your local police station (PSRMS) and handles clearance behind the scenes in 3 working days.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1070000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000007', 'Can I apply for a Rawalpindi Police Character Certificate if I currently live abroad?', 'Yes! A blood relative (father, mother, sibling, or spouse) can apply at Police Khidmat Markaz Rawalpindi with your signed Authority Letter, passport & visa page copies, CNIC copy, and their own original CNIC.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1070000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000007', 'What if I lived in both Rawalpindi and Lahore in the last 5 years?', 'Since both cities are in Punjab, Police Khidmat Markaz can coordinate verification across Punjab districts — just mention all Punjab addresses and stay dates accurately at the counter.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1070000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000007', 'Does MOFA Islamabad attest this certificate?', 'Yes! Bring the original QR-verified Police Character Certificate (ensure your passport number is printed on it) to MOFA Islamabad or courier drop-off for apostille/attestation.', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1080000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000008', 'Can a newborn baby get a Pakistani passport?', 'Yes! As soon as you have the baby’s Union Council Birth Certificate and NADRA B-Form (CRC), you can apply for a child passport at any age.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1080000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000008', 'Do BOTH parents have to go to the Passport Office?', 'At least one parent must accompany the child with BOTH parents’ original CNICs. However, if both parents can attend together, it avoids any chance of being asked for a notarized consent affidavit.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1080000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000008', 'Can I get a 10-year passport for my 8-year-old child?', 'No. Under DGIP rules, children under 15 years are only issued 5-year validity passports because facial features change rapidly. Teenagers aged 15 to 17 can apply for 10-year validity.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1080000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000008', 'What if the parents are divorced or one parent is deceased?', 'If parents are divorced, bring the original Guardianship Certificate / Court Custody Order. If one parent is deceased, bring the original NADRA Death Certificate.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1080000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000008', 'Is the fee for a child passport lower than an adult passport?', 'No, DGIP charges the exact same fee schedule for minors and adults: Rs. 4,500 Normal, Rs. 7,500 Urgent, and Rs. 12,500 Fast Track (36 pages, 5 years).', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1090000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000009', 'Is it mandatory to take my husband’s surname after marriage in Pakistan?', 'No! Under Pakistani law and NADRA policy, women can freely keep their maiden name (father’s surname) while only updating the "Father’s Name" field to "Husband’s Name" and marital status to Married.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1090000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000009', 'Will my 13-digit CNIC number change after marriage?', 'No, your 13-digit CNIC number remains the same for your entire life. Only the card data (marital status, husband’s name, optional surname, and address) is updated.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1090000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000009', 'What if my husband is living abroad and cannot come to NADRA?', 'Your husband can get a marriage verification / NOC undertaking attested from the nearest Pakistani Embassy or Consulate abroad (or verify via NADRA Pak-ID app), which you submit alongside the original Computerized MRC.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1090000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000009', 'Can we also update the husband’s CNIC marital status in the same visit?', 'Yes! Your husband can update his marital status to Married in NADRA’s system at the same counter (no new card is even mandatory for the husband unless he wants a fresh card, though updating status helps when applying for a Family Registration Certificate / FRC).', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1090000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000009', 'Will I need to change my passport after changing my surname on CNIC?', 'Yes, if you change your own surname on your CNIC, you should renew/modify your Pakistani passport so your CNIC and passport names match 100% for travel and visa applications.', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1100000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000010', 'How quickly does an online e-Challan payment clear in the PSCA system?', 'Payments made via PSID (1Bill / e-Pay Punjab / JazzCash / Easypaisa / Bank Apps) update automatically in real time — usually within 1 to 5 minutes.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1100000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000010', 'How do I challenge a wrong e-Challan if the camera photo is not my car?', 'Call the PSCA helpline (15) or visit the PSCA E-Challan Review Center (Qurban Lines Lahore or your city’s Traffic Police HQ) with your vehicle Smart Card and CNIC to file a free dispute.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1100000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000010', 'Does PSCA e-Challan work in Rawalpindi and Islamabad too?', 'Punjab Safe Cities Authority (PSCA) covers Lahore, Rawalpindi, Multan, Faisalabad, Gujranwala, and other Smart Safe Cities in Punjab via echallan.psca.gop.pk. Islamabad Traffic Police uses its separate ITP e-Challan system.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1100000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000010', 'What happens if I do not pay an e-Challan on time?', 'Unpaid e-Challans remain linked to your vehicle registration and CNIC. Multiple unpaid challans can lead to vehicle impoundment at Safe City e-Challan checkpoints and block Excise token tax or vehicle transfer.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1100000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000010', 'Can I pay an e-Challan at an ATM or bank branch if I do not use banking apps?', 'Yes! Print or write down your 17-digit PSID code and pay it at any Bank of Punjab (BOP) branch, NBP branch, 1Link ATM (under Bill Payment → e-Pay Punjab), or local JazzCash/Easypaisa shop.', 5) ON CONFLICT (id) DO NOTHING;
