INSERT INTO public.wait_times (id, process_id, office_name, city, visit_date, wait_minutes, rating, tip, status, created_at) VALUES ('21030000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000003', 'City Traffic Police Licensing Branch Rawalpindi', 'Rawalpindi', '2026-11-16', 40, 4, 'No test needed for renewal. Got my e-Licence PDF the same afternoon!', 'approved', '2026-11-16T09:10:00Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.wait_times (id, process_id, office_name, city, visit_date, wait_minutes, rating, tip, status, created_at) VALUES ('21030000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000003', 'City Traffic Police Licensing Branch Rawalpindi', 'Rawalpindi', '2026-11-14', 50, 4, 'Keep JazzCash balance ready to pay the PSID challan right at the desk.', 'approved', '2026-11-14T11:15:00Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.wait_times (id, process_id, office_name, city, visit_date, wait_minutes, rating, tip, status, created_at) VALUES ('21030000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000003', 'City Traffic Police Licensing Branch Rawalpindi', 'Rawalpindi', '2026-11-11', 35, 5, 'Opted for 5-year renewal at Race Course Ground, super smooth experience.', 'approved', '2026-11-11T09:40:00Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.wait_times (id, process_id, office_name, city, visit_date, wait_minutes, rating, tip, status, created_at) VALUES ('21040000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000004', 'FBR IRIS Online Portal & RTO Islamabad Facilitation Desk', 'Islamabad', '2026-11-16', 15, 5, 'Did the entire NTN registration online at 10 AM — both SMS & Email OTPs arrived in 30 seconds!', 'approved', '2026-11-16T08:40:00Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.wait_times (id, process_id, office_name, city, visit_date, wait_minutes, rating, tip, status, created_at) VALUES ('21040000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000004', 'FBR IRIS Online Portal & RTO Islamabad Facilitation Desk', 'Islamabad', '2026-11-13', 25, 4, 'Make sure your SIM is on your own CNIC — mine worked instantly after switching to my own Jazz SIM.', 'approved', '2026-11-13T10:10:00Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.wait_times (id, process_id, office_name, city, visit_date, wait_minutes, rating, tip, status, created_at) VALUES ('21050000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000005', 'e-Khidmat Markaz Rawalpindi', 'Rawalpindi', '2026-11-15', 55, 4, 'Bring the Rs. 100 stamp paper affidavit already attested from Kachehri so you do not have to leave the line.', 'approved', '2026-11-15T10:05:00Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.wait_times (id, process_id, office_name, city, visit_date, wait_minutes, rating, tip, status, created_at) VALUES ('21050000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000005', 'e-Khidmat Markaz Rawalpindi', 'Rawalpindi', '2026-11-12', 45, 4, 'Paid the Rs. 200 fee via e-Pay Punjab app — reception checked documents in 5 mins.', 'approved', '2026-11-12T11:15:00Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.wait_times (id, process_id, office_name, city, visit_date, wait_minutes, rating, tip, status, created_at) VALUES ('21060000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000006', 'Union Council / e-Khidmat Markaz & RCB Rawalpindi', 'Rawalpindi', '2026-11-15', 40, 4, 'RCB Saddar counter was neat and quick — bring original hospital birth slip and computerized MRC.', 'approved', '2026-11-15T09:30:00Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.wait_times (id, process_id, office_name, city, visit_date, wait_minutes, rating, tip, status, created_at) VALUES ('21060000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000006', 'Union Council / e-Khidmat Markaz & RCB Rawalpindi', 'Rawalpindi', '2026-11-11', 50, 4, 'Double-check baby’s English name spelling on screen before UC Secretary prints final copy.', 'approved', '2026-11-11T10:25:00Z') ON CONFLICT (id) DO NOTHING;
